94	          confirm_action: {
95	            tool_name: action.tool_name,
96	            action: action.action,
97	            params: action.params,
98	          },
99	          history: chatStore.history,
100	          session_context: buildSessionContext(),
101	        }),
102	      });
103	
104	      chatStore.clearPendingAction();
105	      chatStore.addAssistantMessage(response.data.reply ?? 'Done.');
106	      chatStore.chatState = 'idle';
107	    } catch (err) {
108	      const msg =
109	        err instanceof ApiError
110	          ? err.message
111	          : err instanceof Error
112	            ? err.message
113	            : 'Could not complete the action. Please try again.';
114	      chatStore.setError(msg);
115	    }
116	  }
